import json
from pathlib import Path
import unittest
from records.decode import decode

class Records(unittest.TestCase):
    def test_records(self):
        for line, expected in json.loads(Path('samples/records.json').read_text()):
            with self.subTest(line=line):
                self.assertEqual(decode(line), tuple(expected))

